    },
    {
      "id": "inspectParticle",
      "type": "click",
      "teaches": "Each species has a definite Z and A, and summing them across the equation shows mass number and charge are conserved; the three free neutrons are what make the process self-propagating."
    },
    {
      "id": "chainGeneration",
      "type": "slider",
      "label": "Chain-reaction generations",
      "range": [
        0,
        3,
        1
      ],
      "default": 0,
      "teaches": "Because each fission releases three neutrons, the number of fission events multiplies geometrically (1, 3, 9, 27), which is why one neutron can unleash enormous energy."
    }
  ],
  "demo_steps": [
    {
      "title": "A single slow neutron",
      "narration": "One low-energy neutron drifts toward a uranium-235 nucleus. Click the neutron to see that it carries mass number 1 and zero charge — it can approach without electrostatic repulsion.",
      "state": {
        "fissionPhase": "neutron approach",
        "chainGeneration": 0
      }
    },
    {
      "title": "Capture forms U-236",
      "narration": "The nucleus absorbs the neutron, becoming uranium-236. The red outline marks a compound nucleus with too much internal energy to survive.",
      "state": {
        "fissionPhase": "capture: U-236 forms",
        "chainGeneration": 0
      }
    },
    {
      "title": "Deformation and scission",
      "narration": "The excited nucleus stretches into a pinched dumbbell as repulsion between the two halves overcomes the strong force holding it together.",
      "state": {
        "fissionPhase": "deformation & scission",
        "chainGeneration": 0
      }
    },
    {
      "title": "Products, neutrons, and energy",
      "narration": "The nucleus splits into Ba-141 and Kr-92, ejecting three neutrons and releasing a huge burst of energy. Check the equation: 92 = 56 + 36 and 236 = 141 + 92 + 3.",
      "state": {
        "fissionPhase": "products + energy released",
