(function () {
  var FONT = 'Arial, Helvetica, sans-serif';
  var W = 1140, H = 580;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  /* ---------- gradients & markers ---------- */
  function mkGrad(c0, c1, c2) {
    var g = draw.gradient('radial', function (add) {
      add.stop(0, c0); add.stop(0.5, c1); add.stop(1, c2);
    });
    g.attr({ cx: 0.35, cy: 0.32, r: 0.74, fx: 0.33, fy: 0.30 });
    return g;
  }
  var gGreenF = mkGrad('#e2f2ca', '#7cb342', '#41681e');
  var gGreenB = mkGrad('#bcdb9d', '#5e8e30', '#31501a');
  var gGreyF = mkGrad('#ffffff', '#ededE7', '#b7b7ac');
