// @FIGURE_CODE_BEGIN
(function () {
  var FONT = 'Arial, Helvetica, sans-serif';
  var W = 1060, H = 545;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  /* ---------- gradients & markers ---------- */
  function mkGrad(c0, c1, c2) {
    var g = draw.gradient('radial', function (add) {
      add.stop(0, c0); add.stop(0.48, c1); add.stop(1, c2);
    });
    g.attr({ cx: 0.35, cy: 0.31, r: 0.75, fx: 0.32, fy: 0.29 });
    return g;
  }
  var gGreenF = mkGrad('#e6f4d0', '#7cb342', '#3f671d');
  var gGreenB = mkGrad('#c3df a7'.replace(' ', ''), '#5c8c2e', '#2f4d18');
  var gGreyF = mkGrad('#ffffff', '#efefE9', '#b4b4a9');
  var gGreyB = mkGrad('#f2f2ec', '#d6d6cd', '#95958b');

  var mArrow = draw.marker(5, 4, function (add) { add.polygon('0,0 5,2 0,4').fill('#111'); });
  var mArrowSm = draw.marker(6, 5, function (add) { add.polygon('0,0 6,2.5 0,5').fill('#8a8a8a'); });

  /* ---------- layers ---------- */
  var gBg = draw.group();
  gBg.rect(W, H).fill('#ffffff');
  var gHalo = draw.group();
  var gEnergy = draw.group();
  var gNeutronIn = draw.group();
  var gU235 = draw.group();
  var gU236 = draw.group();
  var gKr = draw.group();
  var gBa = draw.group();
  var gN3 = draw.group();
  var gEq = draw.group();
  var gHit = draw.group();
  var gOverlay = draw.group().opacity(0);

  /* ---------- utilities ---------- */
  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }
  var GOLD = Math.PI * (3 - Math.sqrt(5));

  /* Dense space-filling ball: nested Fibonacci shells */
  function ballPoints(R, baseR, rng) {
    var pts = [];
    function shell(rad, spacing) {
      if (rad < baseR * 0.6) return;
      var N = Math.max(10, Math.round(4 * Math.PI * rad * rad / Math.pow(spacing * baseR, 2)));
      var j = baseR * 0.16;
      for (var i = 0; i < N; i++) {
        var z = 1 - 2 * (i + 0.5) / N;
        var rr = Math.sqrt(Math.max(0, 1 - z * z));
        var phi = i * GOLD;
        pts.push([
          rad * rr * Math.cos(phi) + (rng() * 2 - 1) * j,
          rad * rr * Math.sin(phi) + (rng() * 2 - 1) * j,
          rad * z + (rng() * 2 - 1) * j
        ]);
      }
    }
    shell(R, 1.62);
    shell(R * 0.70, 1.80);
    shell(R * 0.40, 2.10);
    return pts;
  }

  function drawSpheres(g, cx, cy, pts, baseR, Rz, rng) {
    pts.sort(function (a, b) { return a[2] - b[2]; });
    for (var i = 0; i < pts.length; i++) {
      var p = pts[i];
      var d = (p[2] / Rz + 1) / 2; if (d < 0) d = 0; if (d > 1) d = 1;
      var r = baseR * (0.80 + 0.28 * d);
      var green = rng() < 0.42;
      var grad = green ? (d > 0.46 ? gGreenF : gGreenB) : (d > 0.46 ? gGreyF : gGreyB);
      g.circle(r * 2).center(cx + p[0], cy + p[1]).fill(grad)
        .stroke({ color: green ? '#4b7a22' : '#c6c6ba', width: 0.6, opacity: 0.55 });
    }
  }

  function ballNucleus(g, cx, cy, R, baseR, seed) {
    var rng = mulberry32(seed);
    drawSpheres(g, cx, cy, ballPoints(R, baseR, rng), baseR, R, mulberry32(seed + 7));
  }

  /* Dumbbell (pinched) nucleus point cloud */
  function dumbbellPoints(Ra, Dh, nw, baseR, rng) {
    var pts = [];
    function neckR(y) {
      var t = Math.min(1, Math.abs(y) / Dh);
      return nw + (Ra * 0.92 - nw) * t * t;
    }
    function inLobe(x, y, z, s, rad) {
      var dy = y - s * Dh;
      return x * x + dy * dy + z * z <= rad * rad;
    }
    function inNeck(x, y, z) {
      if (Math.abs(y) >= Dh) return false;
      var nr = neckR(y);
      return x * x + z * z <= nr * nr;
    }
    [1, -1].forEach(function (s) {
      [[Ra, 1.62], [Ra * 0.68, 1.85], [Ra * 0.38, 2.1]].forEach(function (cfg) {
        var rad = cfg[0], spacing = cfg[1];
        if (rad < baseR * 0.6) return;
        var N = Math.max(10, Math.round(4 * Math.PI * rad * rad / Math.pow(spacing * baseR, 2)));
        var j = baseR * 0.16;
        for (var i = 0; i < N; i++) {
          var uz = 1 - 2 * (i + 0.5) / N;
          var ur = Math.sqrt(Math.max(0, 1 - uz * uz));
          var phi = i * GOLD;
          var x = rad * ur * Math.cos(phi) + (rng() * 2 - 1) * j;
          var y = s * Dh + rad * ur * Math.sin(phi) + (rng() * 2 - 1) * j;
          var z = rad * uz + (rng() * 2 - 1) * j;
          if (rad > Ra * 0.9 && inNeck(x, y, z)) continue;
          pts.push([x, y, z]);
        }
      });
    });
    [1, 0.58].forEach(function (scale) {
      var step = 1.5 * baseR;
      for (var y = -Dh + step * 0.4; y <= Dh; y += step) {
        var nr = neckR(y) * scale;
        if (nr < baseR * 0.5) continue;
        var count = Math.max(5, Math.round(2 * Math.PI * nr / (1.6 * baseR)));
