    shell(R, 1.62);
    shell(R * 0.70, 1.80);
    shell(R * 0.40, 2.10);
    return pts;
  }

  function drawSpheres(g, cx, cy, pts, baseR, Rz, rng) {
    pts.sort(function (a, b) { return a[2] - b[2]; });
    for (var i = 0; i < pts.length; i++) {
      var p = pts[i];
      var d = (p[2] / Rz + 1) / 2; if (d < 0) d = 0; if (d > 1) d = 1;
      var r = baseR * (0.80 + 0.28 * d);
      var green = rng() < 0.42;
      var grad = green ? (d > 0.46 ? gGreenF : gGreenB) : (d > 0.46 ? gGreyF : gGreyB);
      g.circle(r * 2).center(cx + p[0], cy + p[1]).fill(grad)
        .stroke({ color: green ? '#4b7a22' : '#c6c6ba', width: 0.6, opacity: 0.55 });
    }
  }

  function ballNucleus(g, cx, cy, R, baseR, seed) {
    var rng = mulberry32(seed);
    drawSpheres(g, cx, cy, ballPoints(R, baseR, rng), baseR, R, mulberry32(seed + 7));
  }

  /* Dumbbell (pinched) nucleus point cloud */
  function dumbbellPoints(Ra, Dh, nw, baseR, rng) {
    var pts = [];
    function neckR(y) {
      var t = Math.min(1, Math.abs(y) / Dh);
      return nw + (Ra * 0.92 - nw) * t * t;
    }
    function inLobe(x, y, z, s, rad) {
      var dy = y - s * Dh;
      return x * x + dy * dy + z * z <= rad * rad;
    }
    function inNeck(x, y, z) {
      if (Math.abs(y) >= Dh) return false;
      var nr = neckR(y);
      return x * x + z * z <= nr * nr;
    }
    [1, -1].forEach(function (s) {
      [[Ra, 1.62], [Ra * 0.68, 1.85], [Ra * 0.38, 2.1]].forEach(function (cfg) {
        var rad = cfg[0], spacing = cfg[1];
        if (rad < baseR * 0.6) return;
        var N = Math.max(10, Math.round(4 * Math.PI * rad * rad / Math.pow(spacing * baseR, 2)));
        var j = baseR * 0.16;
        for (var i = 0; i < N; i++) {
          var uz = 1 - 2 * (i + 0.5) / N;
          var ur = Math.sqrt(Math.max(0, 1 - uz * uz));
          var phi = i * GOLD;
          var x = rad * ur * Math.cos(phi) + (rng() * 2 - 1) * j;
          var y = s * Dh + rad * ur * Math.sin(phi) + (rng() * 2 - 1) * j;
          var z = rad * uz + (rng() * 2 - 1) * j;
          if (rad > Ra * 0.9 && inNeck(x, y, z)) continue;
          pts.push([x, y, z]);
        }
      });
    });
    [1, 0.58].forEach(function (scale) {
      var step = 1.5 * baseR;
      for (var y = -Dh + step * 0.4; y <= Dh; y += step) {
        var nr = neckR(y) * scale;
        if (nr < baseR * 0.5) continue;
        var count = Math.max(5, Math.round(2 * Math.PI * nr / (1.6 * baseR)));
        for (var k = 0; k < count; k++) {
          var ang = k * 2 * Math.PI / count + y * 0.11;
          var j2 = baseR * 0.14;
          var x = nr * Math.cos(ang) + (rng() * 2 - 1) * j2;
          var z = nr * Math.sin(ang) + (rng() * 2 - 1) * j2;
          var yy = y + (rng() * 2 - 1) * j2;
          if (inLobe(x, yy, z, 1, Ra * 0.97) || inLobe(x, yy, z, -1, Ra * 0.97)) continue;
          pts.push([x, yy, z]);
        }
      }
    });
    return pts;
  }

  function txt(g, s, x, y, size, color, weight) {
    var t = g.text(s).font({ size: size, family: FONT, weight: weight || 'normal' }).fill(color || '#111');
    t.cx(x).cy(y);
    return t;
  }
  /* isotope label: mass number over atomic number, then element symbol */
  function isotope(g, x, y, A, Z, sym, size, align) {
    var small = size * 0.66;
    var tA = g.text(String(A)).font({ size: small, family: FONT }).fill('#111');
    var tZ = g.text(String(Z)).font({ size: small, family: FONT }).fill('#111');
    var tS = g.text(sym).font({ size: size, family: FONT }).fill('#111');
    [tA, tZ, tS].forEach(function (t) {
      t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    });
    var nW = Math.max(tA.bbox().width, tZ.bbox().width);
    var sW = tS.bbox().width;
    var gap = size * 0.18;
    var total = nW + gap + sW;
    var left = (align === 'start') ? x : x - total / 2;
    tA.cx(left + nW / 2).cy(y - size * 0.40);
    tZ.cx(left + nW / 2).cy(y + size * 0.40);
    tS.cx(left + nW + gap + sW / 2).cy(y);
    return total;
  }
  function arrow(g, x1, y1, x2, y2, w, col) {
    return g.line(x1, y1, x2, y2)
      .stroke({ color: col || '#111', width: w || 3.4, linecap: 'round' })
      .marker('end', mArrow);
  }

  /* ---------- subtle stage highlight outlines ---------- */
  var haloDefs = [
    { x: 4, y: 150, w: 210, h: 118 },
    { x: 150, y: 80, w: 262, h: 282 },
    { x: 468, y: 22, w: 184, h: 448 },
    { x: 688, y: 14, w: 366, h: 402 }
  ];
  var halos = haloDefs.map(function (d) {
    return gHalo.rect(d.w, d.h).move(d.x, d.y).radius(26)
      .fill('none')
      .stroke({ color: '#d9a441', width: 2, dasharray: '7,7', linecap: 'round' })
      .opacity(0);
  });

  /* ---------- energy starburst (drawn behind the daughter nuclei) ---------- */
  var EX = 812, EY = 205;
  function starburst(g, cx, cy, spikes, rOut, rIn, xf, fill, rot, op) {
    var pts = [];
    for (var i = 0; i < spikes * 2; i++) {
      var ang = rot + i * Math.PI / spikes;
      var rr = (i % 2 === 0) ? rOut * (0.62 + 0.42 * Math.abs(Math.sin(i * 1.93 + 0.55))) : rIn;
      pts.push((cx + xf * rr * Math.cos(ang)).toFixed(1) + ',' + (cy + rr * Math.sin(ang)).toFixed(1));
    }
    return g.polygon(pts.join(' ')).fill(fill).opacity(op == null ? 1 : op);
  }
  starburst(gEnergy, EX, EY, 14, 152, 34, 0.63, '#f8dfa0', 0.15, 0.95);
  starburst(gEnergy, EX, EY, 12, 118, 30, 0.66, '#f2cd6c', 0.62, 0.95);
  starburst(gEnergy, EX, EY, 9, 80, 26, 0.72, '#f6d888', 1.15, 0.95);
  gEnergy.circle(78).center(EX, EY).fill('#fbe9b4');
  var energyTxt = gEnergy.text('Energy').font({ size: 26, family: FONT }).fill('#2a2a2a');
  energyTxt.attr({ 'paint-order': 'stroke', stroke: '#fdf3d6', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  energyTxt.cx(EX).cy(EY);

  /* ---------- incoming neutron ---------- */
  arrow(gNeutronIn, 48, 200, 168, 200);
  [150, 168, 188, 206, 224].forEach(function (a, i) {
    var rad = a * Math.PI / 180, len = 46 + (i % 2) * 14;
    gNeutronIn.line(172, 198, 172 + len * Math.cos(rad), 198 + len * Math.sin(rad))
      .stroke({ color: '#d6dac7', width: 4.5, linecap: 'round' });
  });
  gNeutronIn.circle(30).center(26, 200).fill(gGreyF).stroke({ color: '#c6c6ba', width: 0.8 });
  isotope(gNeutronIn, 26, 244, 1, 0, 'n', 26);

  /* ---------- U-235 ---------- */
  ballNucleus(gU235, 268, 200, 104, 13.5, 20240501);
  isotope(gU235, 268, 340, 235, 92, 'U', 32);

  /* ---------- U-236 pinched dumbbell ---------- */
  var DX = 556, DY = 205, Ra = 60, Dh = 104, NW = 20, dBaseR = 13;
  (function () {
    var Ra2 = Ra + dBaseR * 0.88, nw2 = NW + dBaseR * 0.88;
    var ax = Ra2 * 0.743, ay = Ra2 * 0.669;
    var p = 'M ' + (DX + ax) + ' ' + (DY - Dh + ay) +
      ' A ' + Ra2 + ' ' + Ra2 + ' 0 1 0 ' + (DX - ax) + ' ' + (DY - Dh + ay) +
      ' Q ' + (DX - (2 * nw2 - ax)) + ' ' + DY + ' ' + (DX - ax) + ' ' + (DY + Dh - ay) +
      ' A ' + Ra2 + ' ' + Ra2 + ' 0 1 0 ' + (DX + ax) + ' ' + (DY + Dh - ay) +
      ' Q ' + (DX + (2 * nw2 - ax)) + ' ' + DY + ' ' + (DX + ax) + ' ' + (DY - Dh + ay) + ' Z';
    gU236.path(p).fill('#ffffff').stroke({ color: '#9e2f1c', width: 2.4, linejoin: 'round' });
  })();
  (function () {
    var rng = mulberry32(777001);
    var pts = dumbbellPoints(Ra, Dh, NW, dBaseR, rng);
    drawSpheres(gU236, DX, DY, pts, dBaseR, Ra, mulberry32(4242));
  })();
  arrow(gU236, 392, 205, 484, 205);
  isotope(gU236, DX, 406, 236, 92, 'U', 32);
  txt(gU236, 'Unstable nucleus', DX, 448, 27, '#111');

  /* ---------- daughter nuclei ---------- */
  arrow(gKr, 622, 112, 726, 70);
  ballNucleus(gKr, 810, 85, 64, 12.5, 33210);
  isotope(gKr, 886, 76, 92, 36, 'Kr', 32, 'start');

  arrow(gBa, 624, 288, 730, 314);
  ballNucleus(gBa, 816, 330, 74, 13, 91177);
  isotope(gBa, 898, 322, 141, 56, 'Ba', 32, 'start');

  /* ---------- three emitted neutrons ---------- */
  arrow(gN3, 912, 142, 954, 128);
  arrow(gN3, 912, 180, 954, 178);
  arrow(gN3, 912, 222, 954, 240);
  gN3.circle(28).center(974, 124).fill(gGreyF).stroke({ color: '#c6c6ba', width: 0.8 });
  gN3.circle(32).center(976, 176).fill(gGreyF).stroke({ color: '#c6c6ba', width: 0.8 });
  gN3.circle(28).center(978, 252).fill(gGreyF).stroke({ color: '#c6c6ba', width: 0.8 });
  (function () {
    var t3 = gN3.text('3').font({ size: 30, family: FONT }).fill('#111');
    t3.cx(1004).cy(176);
    isotope(gN3, 1018, 176, 1, 0, 'n', 28, 'start');
  })();

  /* ---------- bottom balanced equation ---------- */
  (function () {
    var size = 32, y = 505, cur = 0, gap = 11;
    function iso(A, Z, s) { cur += isotope(gEq, cur, y, A, Z, s, size, 'start') + gap; }
    function plain(s) {
      var t = gEq.text(s).font({ size: size, family: FONT }).fill('#111');
      var w = t.bbox().width; t.cx(cur + w / 2).cy(y); cur += w + gap;
    }
    function arr(len) {
      gEq.line(cur + 6, y, cur + len - 8, y)
        .stroke({ color: '#111', width: 2.8, linecap: 'round' }).marker('end', mArrow);
      cur += len + gap;
    }
    iso(235, 92, 'U'); plain('+'); iso(1, 0, 'n'); arr(92);
    iso(236, 92, 'U'); arr(92);
    iso(141, 56, 'Ba'); plain('+'); iso(92, 36, 'Kr'); plain('+'); plain('3'); iso(1, 0, 'n');
    var bb = gEq.bbox();
    gEq.transform({ translate: [(W - bb.width) / 2 - bb.x, 0] });
  })();

  /* ---------- click-to-inspect ---------- */
  var parts = {
    neutron: {
      g: gNeutronIn, title: 'Neutron  ¹₀n',
      body: 'Mass number A = 1, atomic number Z = 0. Because it carries no charge it feels no Coulomb repulsion and can drift straight into a nucleus. Slow ("thermal") neutrons are captured most readily by U-235.'
    },
    u235: {
      g: gU235, title: 'Uranium-235  ²³⁵₉₂U',
      body: 'Z = 92 protons (green) and 143 neutrons (grey), A = 235. It is fissile: absorbing even a slow neutron supplies enough excitation energy to deform and split the nucleus.'
    },
    u236: {
      g: gU236, title: 'Uranium-236 — compound nucleus',
      body: 'Z = 92, A = 236 right after capture. The extra binding energy leaves it violently excited, so it oscillates and stretches into a pinched dumbbell. The dark red contour marks this short-lived, unstable state.'
    },
    kr: {
      g: gKr, title: 'Krypton-92  ⁹²₃₆Kr',
      body: 'Z = 36, A = 92. One of the two fission fragments. The two positively charged fragments repel each other fiercely, which is where most of the released energy appears as kinetic energy.'
    },
    ba: {
      g: gBa, title: 'Barium-141  ¹⁴¹₅₆Ba',
      body: 'Z = 56, A = 141. Check the bookkeeping: 56 + 36 = 92 protons, and 141 + 92 + 3 = 236 nucleons. Charge and mass number are conserved.'
    },
    n3: {
      g: gN3, title: 'Three free neutrons',
      body: 'Fission consumes one neutron and releases three. Each free neutron can induce another fission, so the multiplication factor exceeds 1 — this surplus is exactly what makes the reaction self-sustaining.'
    },
    energy: {
      g: gEnergy, title: 'Energy release (~200 MeV)',
      body: 'Each fission converts a tiny amount of mass into about 200 MeV, mostly kinetic energy of the fragments. That is roughly 100 million times the energy of a typical chemical reaction per atom.'
    }
  };
  var selected = null;
  function clearSelect() {
    selected = null;
    Object.keys(parts).forEach(function (k) { parts[k].g.animate(180).opacity(1); });
    gEq.animate(180).opacity(1);
    hidePopup();
  }
  function selectPart(k) {
    if (selected === k) { clearSelect(); return; }
    selected = k;
    Object.keys(parts).forEach(function (kk) {
      parts[kk].g.animate(180).opacity(kk === k ? 1 : 0.20);
    });
    gEq.animate(180).opacity(0.28);
    showPopup(parts[k].title, parts[k].body);
  }
  gBg.rect(W, H).fill('#ffffff').opacity(0.001).on('click', clearSelect);

  function hit(shape, key, tip) {
    shape.fill('#ffffff').opacity(0.001).css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { selectPart(key); });
  }
  hit(gHit.circle(58).center(26, 212), 'neutron', 'Incoming neutron — A 1, Z 0 (click)');
  hit(gHit.circle(224).center(268, 200), 'u235', 'Uranium-235 nucleus — Z 92, A 235 (click)');
  hit(gHit.ellipse(160, 360).center(DX, DY), 'u236', 'Uranium-236 compound nucleus — unstable (click)');
  hit(gHit.circle(150).center(810, 85), 'kr', 'Krypton-92 fragment — Z 36, A 92 (click)');
  hit(gHit.circle(168).center(816, 330), 'ba', 'Barium-141 fragment — Z 56, A 141 (click)');
  hit(gHit.rect(120, 176).move(930, 100), 'n3', '3 emitted neutrons — the chain-reaction surplus (click)');
  hit(gHit.circle(92).center(EX, EY), 'energy', '~200 MeV released per fission (click)');

  /* ---------- chain-reaction overlay ---------- */
  function drawChain(gen) {
    gOverlay.clear();
    if (gen <= 0) { gOverlay.opacity(0); gOverlay.css('pointer-events', 'none'); return; }
    gOverlay.opacity(1); gOverlay.css('pointer-events', 'all');
    gOverlay.rect(W, H).fill('#ffffff').opacity(0.96);

    var xs = [145, 400, 660, 902];
    var rs = [19, 13.5, 8.5, 5.2];
    var levels = [[{ y: 285, spread: 400 }]];
    for (var k = 1; k <= gen; k++) {
      var next = [];
      levels[k - 1].forEach(function (p) {
        var s = p.spread / 3;
        [-1, 0, 1].forEach(function (d) { next.push({ y: p.y + d * s, spread: s, parent: p }); });
      });
      levels.push(next);
    }
    for (var L = 1; L <= gen; L++) {
      var op = (L < gen) ? 0.3 : 0.95;
      levels[L].forEach(function (n) {
        var x1 = xs[L - 1] + rs[L - 1] + 2, y1 = n.parent.y;
        var x2 = xs[L] - rs[L] - 3, y2 = n.y;
        gOverlay.line(x1, y1, x2, y2).stroke({ color: '#8a8a8a', width: 1.4 })
          .marker('end', mArrowSm).opacity(op);
        gOverlay.circle(7).center(x1 + (x2 - x1) * 0.55, y1 + (y2 - y1) * 0.55)
          .fill(gGreyF).opacity(op);
      });
    }
    for (var L2 = 0; L2 <= gen; L2++) {
      var op2 = (L2 < gen) ? 0.32 : 1;
      levels[L2].forEach(function (n) {
        var c = gOverlay.circle(rs[L2] * 2).center(xs[L2], n.y).fill(gGreenF)
          .stroke({ color: '#41681e', width: 0.9 }).opacity(op2);
        c.css('cursor', 'pointer')
          .on('mousemove', function (e) { showTooltip('One fission event: U-235 + n → Ba + Kr + 3n', e); })
          .on('mouseleave', hideTooltip);
      });
      var lt = gOverlay.text('Gen ' + L2).font({ size: 18, family: FONT }).fill('#555');
      lt.cx(xs[L2]).cy(500);
      var ct = gOverlay.text(Math.pow(3, L2) + (Math.pow(3, L2) === 1 ? ' fission' : ' fissions'))
        .font({ size: 16, family: FONT }).fill('#777');
      ct.cx(xs[L2]).cy(524);
    }
    var thisGen = Math.pow(3, gen);
    var total = (Math.pow(3, gen + 1) - 1) / 2;
    var mev = total * 200;
    gOverlay.text('Generation ' + gen).font({ size: 28, family: FONT, weight: 'bold' }).fill('#1a1a1a').x(46).cy(44);
    gOverlay.text('this generation: 3^' + gen + ' = ' + thisGen + ' fissions').font({ size: 18, family: FONT }).fill('#333').x(46).cy(80);
    gOverlay.text('cumulative fissions: ' + total).font({ size: 18, family: FONT }).fill('#333').x(46).cy(106);
    gOverlay.text('energy released ≈ ' + mev.toLocaleString() + ' MeV  (' + (total * 3.2e-11).toExponential(1) + ' J)')
      .font({ size: 18, family: FONT }).fill('#a2571a').x(46).cy(132);
    var t5 = gOverlay.text('Each fission emits 3 neutrons, and each of those can split another U-235:  1 → 3 → 9 → 27.')
      .font({ size: 17, family: FONT }).fill('#555');
    t5.cx(W / 2).cy(H - 14);
  }

  /* ---------- controls ---------- */
  var PHASES = ['neutron approach', 'capture: U-236 forms', 'deformation & scission', 'products + energy released'];
  var phaseIdx = 0;
  window.set_fissionPhase = function (i) {
    phaseIdx = i;
    var inp = document.getElementById('fissionPhaseInput');
    if (inp) inp.value = String(i);
    for (var k = 0; k < 4; k++) {
      halos[k].animate(200).opacity(k === i ? 0.55 : 0);
      var b = document.getElementById('phaseBtn' + k);
      if (b) b.className = (k === i) ? 'active' : '';
    }
  };
  window.update_chainGeneration = function (v) { drawChain(v); };
  function setChainUI(v) {
    var s = document.getElementById('chainGenerationInput');
    var o = document.getElementById('chainGenerationVal');
    if (s) s.value = String(v);
    if (o) o.value = String(v);
    window.update_chainGeneration(v);
  }
  var playTimer = null;
  window.trigger_playFission = function () {
    if (playTimer) { clearInterval(playTimer); playTimer = null; }
    clearSelect();
    setChainUI(0);
    var i = 0;
    window.set_fissionPhase(0);
    playTimer = setInterval(function () {
      i++;
      if (i > 3) { clearInterval(playTimer); playTimer = null; return; }
      window.set_fissionPhase(i);
    }, 1100);
  };

  /* ---------- demo steps ---------- */
  var steps = [
    { title: 'A single slow neutron', narration: 'One low-energy neutron drifts toward a uranium-235 nucleus. Click the neutron to see that it carries mass number 1 and zero charge — it can approach without electrostatic repulsion.', state: { fissionPhase: 'neutron approach', chainGeneration: 0 } },
    { title: 'Capture forms U-236', narration: 'The nucleus absorbs the neutron, becoming uranium-236. The red outline marks a compound nucleus with too much internal energy to survive.', state: { fissionPhase: 'capture: U-236 forms', chainGeneration: 0 } },
    { title: 'Deformation and scission', narration: 'The excited nucleus stretches into a pinched dumbbell as repulsion between the two halves overcomes the strong force holding it together.', state: { fissionPhase: 'deformation & scission', chainGeneration: 0 } },
    { title: 'Products, neutrons, and energy', narration: 'The nucleus splits into Ba-141 and Kr-92, ejecting three neutrons and releasing a huge burst of energy. Check the equation: 92 = 56 + 36 and 236 = 141 + 92 + 3.', state: { fissionPhase: 'products + energy released', chainGeneration: 0 } },
    { title: 'One fission becomes three', narration: 'Each of the three emitted neutrons can strike another U-235 nucleus. Generation 1 turns one fission into three.', state: { fissionPhase: 'products + energy released', chainGeneration: 1 } },
    { title: 'The chain runs away', narration: 'Advance the generations: 1 → 3 → 9 → 27 fissions, with energy released multiplying just as fast. This geometric growth is the self-sustaining chain reaction behind reactors and weapons.', state: { fissionPhase: 'products + energy released', chainGeneration: 3 } }
  ];
  var stepIdx = 0;
  function applyStep(i) {
    stepIdx = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[stepIdx];
    if (playTimer) { clearInterval(playTimer); playTimer = null; }
    clearSelect();
    window.set_fissionPhase(PHASES.indexOf(s.state.fissionPhase));
    setChainUI(s.state.chainGeneration);
    var n = document.getElementById('demoNarration');
    if (n) n.innerHTML = '<b>' + s.title + '.</b> ' + s.narration;
    var l = document.getElementById('stepLabel');
    if (l) l.textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
  }
  window.nextStep = function () { applyStep(stepIdx + 1); };
  window.prevStep = function () { applyStep(stepIdx - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

